create type public.notification_status as enum ('pending','processing','sent','failed','cancelled');
create table public.notification_outbox (id uuid primary key default gen_random_uuid(), event_type text not null, entity_type text not null, entity_id uuid not null, threshold_key text not null, channel text, scheduled_for timestamptz not null, status public.notification_status not null default 'pending', attempt_count smallint not null default 0, last_error text, sent_at timestamptz, deduplication_key text not null unique, created_at timestamptz not null default now(), created_by uuid references auth.users(id), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id), deleted_at timestamptz, deleted_by uuid references auth.users(id));
